 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full separator rows and columns partition the canvas into cells.
    sep = 5
    row_bands = []
    start = 0
    for r in range(h):
        if all(v == sep for v in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))
    col_bands = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == sep for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))

    # First cell of each band row contains that row's color key.
    row_colors = []
    for r0, r1 in row_bands:
        vals = [grid[r][c] for r in range(r0, r1) for c in range(*col_bands[0]) if grid[r][c] != 0]
        row_colors.append(vals[0] if vals else 0)

    # The template is the non-marker shape occupying one cell; marker cells
    # are solid 2x2 squares. Collect its within-cell coordinates.
    template = None
    max_count = 0
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            cells = [(r-r0, c-c0, grid[r][c]) for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0]
            if len(cells) > 4 and len(cells) > max_count:
                max_count = len(cells)
                template = [(dr, dc) for dr, dc, _ in cells]
    if template is None:
        # Fallback: use the nonzero pattern in the first non-marker cell.
        for r0, r1 in row_bands:
            for c0, c1 in col_bands:
                cells = [(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0]
                if cells:
                    template = cells
                    break
            if template:
                break
    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(row_bands):
        color = row_colors[ri]
        for c0, c1 in col_bands:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            for dr, dc in template:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = color
    return out
